using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpHttpServer;

[McpServerResourceType]
public class ConfigResources
{
    /// <summary>A direct resource that returns the current app configuration.</summary>
    [McpServerResource(UriTemplate = "config://app", Name = "AppConfig",
        Title = "Application Configuration", MimeType = "application/json")]
    public static string GetAppConfig()
    {
        var config = new
        {
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { DarkMode = true, BetaAccess = false }
        };

        return System.Text.Json.JsonSerializer.Serialize(config,
            new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }

    /// <summary>A resource template that returns configuration for a named section.</summary>
    [McpServerResource(UriTemplate = "config://app/sections/{section}",
        Name = "SectionConfig", Title = "Section Configuration", MimeType = "application/json")]
    public static string GetSectionConfig(string section)
    {
        var sections = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
        {
            ["database"] = new { Host = "localhost", Port = 5432, Database = "appdb" },
            ["logging"]  = new { Level = "Information", Format = "json" },
            ["cache"]    = new { Provider = "memory", TtlMinutes = 15 },
        };

        if (!sections.TryGetValue(section, out var data))
            return System.Text.Json.JsonSerializer.Serialize(new { Error = $"Unknown section: {section}" });

        return System.Text.Json.JsonSerializer.Serialize(data,
            new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }
}

